public static TmpCustVendTrans getCustAccountingBalance(TmpCustVendTrans _tmpCustVendTransCurrency, CustAccount _custAccount,
                                                        boolean _isCurrentCustomer)
{
    TmpCustVendTrans   tmpCustVendTransHelper;
    AmountMST          totalAmountMST, totalNetEstimatedAmount;
    AVAFCMCalcBalance calcBalance = CustParameters::find().AVAFCMCalcBalance;

    tmpCustVendTransHelper.setTmpData(_tmpCustVendTransCurrency);

    //Accounting balance of current customer
    if (_isCurrentCustomer)
    {
        while select sum(amountMST), sum(AVAFPLNetEstimatedAmount) from tmpCustVendTransHelper
            where tmpCustVendTransHelper.AccountNum == _custAccount
        {
            if(calcBalance == AVAFCMCalcBalance::Gross)
            {
                totalAmountMST          += tmpCustVendTransHelper.amountMST;
            }
            else
            {
                totalAmountMST          += tmpCustVendTransHelper.AVAFPLNetEstimatedAmount;
            }

            totalNetEstimatedAmount += tmpCustVendTransHelper.AVAFPLNetEstimatedAmount;
        }

        _tmpCustVendTransCurrency.clear();
        _tmpCustVendTransCurrency.AccountNum             = _custAccount;
        _tmpCustVendTransCurrency.CurrencyCode           = CompanyInfoHelper::standardCurrency();
        _tmpCustVendTransCurrency.AmountMst              = totalAmountMST;
        _tmpCustVendTransCurrency.AmountCur              = 0;
        _tmpCustVendTransCurrency.TotalAmountMst         = 0;
        _tmpCustVendTransCurrency.AVAFPLNetEstimatedAmount = totalNetEstimatedAmount;
        _tmpCustVendTransCurrency.Txt                    = "@AVAFCM:AccountBalanceCurrentCustomer";
        _tmpCustVendTransCurrency.insert();
    }
    //Accounting balance of remaining customers
    else
    {
        while select sum(amountMST), sum(AVAFPLNetEstimatedAmount) from tmpCustVendTransHelper
            where tmpCustVendTransHelper.AccountNum != _custAccount
        {
            if(calcBalance == AVAFCMCalcBalance::Gross)
            {
                totalAmountMST          += tmpCustVendTransHelper.amountMST;
            }
            else
            {
                totalAmountMST          += tmpCustVendTransHelper.AVAFPLNetEstimatedAmount;
            }

            totalNetEstimatedAmount += tmpCustVendTransHelper.AVAFPLNetEstimatedAmount;
        }

        _tmpCustVendTransCurrency.clear();
        _tmpCustVendTransCurrency.CurrencyCode           = CompanyInfoHelper::standardCurrency();
        _tmpCustVendTransCurrency.AmountMst              = totalAmountMST;
        _tmpCustVendTransCurrency.AmountCur              = 0;
        _tmpCustVendTransCurrency.TotalAmountMst         = 0;
        _tmpCustVendTransCurrency.AVAFPLNetEstimatedAmount = totalNetEstimatedAmount;
        _tmpCustVendTransCurrency.Txt                    = "@AVAFCM:AccountBalanaceOtherCustomer";
        _tmpCustVendTransCurrency.insert();
    }

    return  _tmpCustVendTransCurrency;
}
